import { isArraysEqualDeeply } from "../../utils/compareElementsUtils/isArraysEqualDeeply";
import { isElementsEqual } from "../../utils/compareElementsUtils/isElementsEqual";
export function getNumberOfChangedFilters(defaultState, newState) {
    let changes = 0;
    Object.keys(defaultState).forEach(key => {
        const oldValue = (defaultState)[key];
        const newValue = (newState)[key];
        if (!newValue) {
            // If the new value is not set, then the component is not visible, ignore it
            return;
        }
        if (Array.isArray(oldValue) && Array.isArray(newValue)) {
            if (!isArraysEqualDeeply(oldValue, newValue)) {
                changes++;
            }
            return;
        }
        if (typeof oldValue === "object" && typeof newValue === "object") {
            if (!isElementsEqual(oldValue, newValue)) {
                changes++;
            }
            return;
        }
        if (oldValue !== newValue) {
            changes++;
        }
    });
    Object.keys(newState).forEach(key => {
        if (defaultState[key] === undefined) {
            changes++;
        }
    });
    return changes;
}
